import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.*;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Collections;

@RunWith(MockitoJUnitRunner.class)
public class CommentsConfigurationTest {

    @Mock
    private Map<String, List<String>> map;

    public CommentsConfiguration commentsConfiguration(Map<String, List<String>> map) {
        return new CommentsConfiguration(map);
    }

    @Test
    public void newCommentsConfiguration returnsNewInstance() {
        when(map.get("test")).thenReturn(new ArrayList<>());
        CommentsConfiguration config = commentsConfiguration(map);
        assertNotNull(config);
    }

    @Test
    public void newCommentsConfigurationWithMapReturnsNewInstance() {
        when(map.get("test")).thenReturn(Collections.singletonList("Comment1"));
        CommentsConfiguration config = commentsConfiguration(map);
        assertEquals(1, config.getAllComments().get("test").size());
    }

    @Test
    public void setCommentSetsCommentForPath() {
        CommentsConfiguration config = new CommentsConfiguration();
        config.setComment("test", "Comment1");
        assertTrue(config.getAllComments().containsKey("test"));
        assertEquals(1, config.getAllComments().get("test").size());
    }

    @Test
    public void setCommentWithEmptyLineSetsEmptyLineWithoutMarker() {
        CommentsConfiguration config = new CommentsConfiguration();
        config.setComment("test", "", "Comment1");
        assertTrue(config.getAllComments().containsKey("test"));
        assertEquals(2, config.getAllComments().get("test").size());
        assertTrue(config.getAllComments().get("test").get(0).isEmpty());
    }

    @Test
    public void setCommentOverwritesExistingCommentForPath() {
        CommentsConfiguration config = new CommentsConfiguration();
        config.setComment("test", "OldComment1");
        config.setComment("test", "NewComment2");
        assertEquals(2, config.getAllComments().get("test").size());
        assertTrue(config.getAllComments().get("test").containsAll(List.of("NewComment2")));
    }

    @Test
    public void getAllCommentsReturnsReadOnlyView() {
        CommentsConfiguration config = new CommentsConfiguration();
        config.setComment("test", "Comment1");
        config.setComment("test2", "Comment2");
        assertTrue(config.getAllComments().containsKey("test"));
        assertTrue(config.getAllComments().containsKey("test2"));
    }
}
