    }

    public void setComment(String path, String comment, String marker) {
        if (marker.isEmpty()) {
            map.get(path).add(comment);
        } else {
            map.putIfAbsent(path, new ArrayList<>());
            ((List<String>) map.get(path)).add(comment);
        }
